INSERT INTO dump_descriptions (base_key, description) VALUES ('playerping', 'Adds a per-player ping readout beside the team list, with its color shifting from green toward red as latency rises.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('notsohumbleflaregunchanges', 'Buffs the flare gun projectile with higher damage and speed, lower gravity, a brighter warm light, and a 3,600-second lifetime.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
